"""Copy reviewed figures and generate LaTeX values; never overwrite prose."""
from pathlib import Path
import shutil
import pandas as pd
from .io import ROOT, load_config, save_json, sha256


def latex_escape(text):
    return str(text).replace("&", r"\&").replace("%", r"\%").replace("_", r"\_")


def write_tabular(path, headers, rows, columns=None):
    columns = columns or "l" + "r" * (len(headers)-1)
    body = [r"\begin{tabular}{" + columns + "}", r"\toprule", " & ".join(headers) + r" \\", r"\midrule"]
    body += [" & ".join(str(x) for x in row) + r" \\" for row in rows]
    body += [r"\bottomrule", r"\end{tabular}"]
    Path(path).write_text("\n".join(body) + "\n", encoding="utf-8")


def export_report(cfg, target=None):
    dest = Path(target) if target else ROOT.parent / (ROOT.name + "-Report")
    dest = dest.resolve()
    generated = dest / "generated"
    figures = dest / "figures"
    snapshot = dest / "evidence"
    for folder in [generated, figures, snapshot]:
        folder.mkdir(parents=True, exist_ok=True)
    tables = ROOT / "results/tables"
    summary = load_config("results/summary.json")
    profile = load_config("results/data_profile.json")
    selection = load_config("results/selection.json")
    month = pd.read_csv(tables / "monthly_retention.csv")
    test = month.loc[month.split.eq("test")]
    known = pd.read_csv(tables / "customer_sensitivity.csv")
    small = pd.read_csv(tables / "basket_size_sensitivity.csv")
    bench = pd.read_csv(tables / "benchmark.csv")
    protocol = load_config("results/protocol.json")
    number = lambda n: f"{int(n):,}"
    pct = lambda x: f"{float(x)*100:.1f}\\%"
    macros = {"RawRows": number(profile["raw_rows"]), "CleanRows": number(profile["clean_rows"]), "AllOrders": number(profile["all_country_baskets"]), "UKOrders": number(profile["uk_baskets"]), "CleanProducts": number(profile["clean_products"]), "TrainOrders": number(protocol["discovery_orders"]), "ValidationOrders": number(month.loc[month.split.eq("validation"), "orders"].sum()), "TestOrders": number(test.orders.sum()), "MissingCustomers": number(profile["missing_by_column"]["CustomerID"]), "MissingCustomerPct": pct(profile["missing_by_column"]["CustomerID"]/profile["raw_rows"]), "SelectedRules": number(summary["selected_rules"]), "RuleMonths": number(summary["test_rule_months"]), "RetainedRuleMonths": number(summary["test_retained_rule_months"]), "MeanRetention": pct(summary["mean_monthly_test_retention"]), "AllMonthsRules": number(summary["rules_retained_all_test_months"]), "AllMonthsPct": pct(summary["rules_retained_all_test_months"]/summary["selected_rules"]), "ZeroMonthsRules": number(summary["rules_retained_no_test_month"]), "Coverage": pct(summary["test_evaluation_coverage"]), "KnownRetention": pct(known.retention_rate.mean()), "SmallBasketRetention": pct(small.retention_rate.mean()), "ValidationRetention": pct(selection["validation_retention"]), "MaxBenchmarkMemory": f"{summary['benchmark_max_peak_rss_mib']:.1f}", "ExperimentSeconds": f"{summary['experiment_wall_seconds']:.1f}"}
    generated.joinpath("results.tex").write_text("% Generated by the CODE repository. Edit source data/configuration, not these values.\n" + "\n".join("\\newcommand{\\" + key + "}{" + val + "}" for key, val in macros.items()) + "\n", encoding="utf-8")
    audit = pd.read_csv(tables / "cleaning_audit.csv")
    labels = {"raw": "Raw line items", "exact_duplicate_lines": "Exact duplicates", "missing_required_basket_fields": "Missing essential basket fields", "cancelled_invoice": "Cancellation invoice rows", "nonpositive_quantity": "Other nonpositive quantity", "nonpositive_price": "Nonpositive price", "non_product_codes": "Non-product codes"}
    write_tabular(generated / "cleaning.tex", ["Sequential step", "Removed", "Remaining"], [[labels[r.step], number(r.removed_rows), number(r.remaining_rows)] for r in audit.itertuples()])
    bench_summary = bench.groupby(["min_support", "algorithm"]).agg(seconds=("seconds", "median"), minimum=("seconds", "min"), maximum=("seconds", "max"), memory=("peak_process_rss_mib", "median"), itemsets=("itemsets", "first")).reset_index()
    write_tabular(generated / "benchmark.tex", ["Support", "Method", "Median s", "Range s", "Peak MiB", "Itemsets"], [[pct(r.min_support), "Apriori LM" if r.algorithm == "apriori" else "FP-Growth", f"{r.seconds:.3f}", f"{r.minimum:.3f}--{r.maximum:.3f}", f"{r.memory:.1f}", number(r.itemsets)] for r in bench_summary.itertuples()], "llrrrr")
    write_tabular(generated / "monthly.tex", ["Month", "Orders", "Evaluable", "Retained", "Retention"], [[r.month, number(r.orders), f"{r.evaluable_rules}/71", f"{r.retained_rules}/71", pct(r.retention_rate)] for r in test.itertuples()])
    grid = pd.read_csv(tables / "threshold_sensitivity.csv").merge(pd.read_csv(tables / "threshold_evaluability.csv")[["configuration", "test_evaluation_coverage", "test_conditional_retention"]], on="configuration", validate="one_to_one")
    write_tabular(generated / "grid.tex", ["Support", "Confidence", "Rules", "Validation", "Test", "Evaluable"], [[pct(r.min_support), pct(r.min_confidence), number(r.rules), pct(r.validation_retention), pct(r.test_retention), pct(r.test_evaluation_coverage)] for r in grid.itertuples()])
    floor = pd.read_csv(tables / "rule_floor_sensitivity.csv")
    write_tabular(generated / "floor.tex", ["Rule floor", "Selected rules", "Validation retention", "Test retention"], [[r.minimum_rules, number(r.rules), pct(r.validation_retention), pct(r.test_retention)] for r in floor.itertuples()])
    means = [("UK primary", test.retention_rate.mean()), ("All countries", pd.read_csv(tables / "country_sensitivity.csv").query("scope == 'All countries'").retention_rate.mean()), ("UK with customer ID", known.retention_rate.mean()), ("UK at most 100 products", small.retention_rate.mean())]
    write_tabular(generated / "populations.tex", ["Evaluation population", "Mean monthly retention"], [[name, pct(rate)] for name, rate in means])
    source_files = [ROOT / "data/source_manifest.json", ROOT / "results/summary.json", ROOT / "results/protocol.json", ROOT / "results/selection.json", ROOT / "results/verification.json", ROOT / "results/supplemental_protocol.json", ROOT / "results/data_profile.json", ROOT / "results/environment.json"] + sorted(tables.glob("*.csv"))
    if (ROOT / "results/report_diagnostics.json").exists():
        source_files.append(ROOT / "results/report_diagnostics.json")
    receipts = []
    for source in source_files:
        shutil.copy2(source, snapshot / source.name)
        receipts.append({"file": source.relative_to(ROOT).as_posix(), "sha256": sha256(source)})
    for source in sorted((ROOT / "results/figures").glob("*")):
        if source.suffix not in {".png", ".pdf", ".svg"}:
            continue
        shutil.copy2(source, figures / source.name)
        receipts.append({"file": source.relative_to(ROOT).as_posix(), "sha256": sha256(source)})
    save_json({"code_repository": "https://github.com/Chikit-WONG/AIAA3111-Introduction_to_Data_Mining-Final_Project", "configuration_sha256": protocol["configuration_sha256"], "files": receipts}, snapshot / "export_manifest.json")
    print(f"Exported figures, evidence and LaTeX tables to {dest}; narrative sections preserved.")
